{
  "id": "2368814",
  "schema": "prospeccao",
  "name": "execucoes",
  "rls_enabled": false,
  "size": "48 kB",
  "comment": "Histórico de cada execução do fluxo n8n por empresa/departamento",
  "columns": [
    {
      "attnum": 1,
      "attname": "id",
      "type": "integer",
      "nullable": false,
      "default_value": "nextval('prospeccao.execucoes_id_seq'::regclass)"
    },
    {
      "attnum": 2,
      "attname": "empresa_id",
      "type": "integer",
      "nullable": false,
      "default_value": null
    },
    {
      "attnum": 3,
      "attname": "departamento",
      "type": "text",
      "nullable": true,
      "default_value": null
    },
    {
      "attnum": 4,
      "attname": "total_encontrados",
      "type": "integer",
      "nullable": true,
      "default_value": "0"
    },
    {
      "attnum": 5,
      "attname": "total_inseridos",
      "type": "integer",
      "nullable": true,
      "default_value": "0"
    },
    {
      "attnum": 6,
      "attname": "total_duplicatas",
      "type": "integer",
      "nullable": true,
      "default_value": "0"
    },
    {
      "attnum": 7,
      "attname": "status",
      "type": "text",
      "nullable": false,
      "default_value": "'iniciado'::text"
    },
    {
      "attnum": 8,
      "attname": "erro_msg",
      "type": "text",
      "nullable": true,
      "default_value": null
    },
    {
      "attnum": 9,
      "attname": "executado_por",
      "type": "text",
      "nullable": true,
      "default_value": null
    },
    {
      "attnum": 10,
      "attname": "created_at",
      "type": "timestamp with time zone",
      "nullable": false,
      "default_value": "now()"
    }
  ],
  "constraints": [
    {
      "conname": "execucoes_status_check",
      "type": "CHECK",
      "definition": "CHECK ((status = ANY (ARRAY['iniciado'::text, 'concluido'::text, 'erro'::text, 'sem_resultado'::text])))"
    },
    {
      "conname": "execucoes_empresa_id_fkey",
      "type": "FOREIGN KEY",
      "definition": "FOREIGN KEY (empresa_id) REFERENCES prospeccao.empresas(id) ON DELETE CASCADE"
    },
    {
      "conname": "execucoes_pkey",
      "type": "PRIMARY KEY",
      "definition": "PRIMARY KEY (id)"
    }
  ],
  "indexes": [
    {
      "name": "execucoes_pkey",
      "definition": "CREATE UNIQUE INDEX execucoes_pkey ON prospeccao.execucoes USING btree (id)",
      "is_unique": true,
      "is_primary": true
    },
    {
      "name": "idx_execucoes_empresa",
      "definition": "CREATE INDEX idx_execucoes_empresa ON prospeccao.execucoes USING btree (empresa_id)",
      "is_unique": false,
      "is_primary": false
    }
  ]
}
